<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatórios · Fiscaliza Obras</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="app-body"><div class="shell"><aside class="sidebar"><div class="brand">Fiscaliza Obras</div><nav><a href="/">Visão geral</a><a href="/works<?= $condoId ? '?condo='.(int)$condoId : '' ?>">Obras</a><a class="active" href="/reports<?= $condoId ? '?condo='.(int)$condoId : '' ?>">Relatórios</a></nav></aside><main class="content"><header class="topbar"><div><p class="eyebrow">Gestão e indicadores</p><h1>Relatórios de obras</h1><p class="muted">Visão consolidada por condomínio, situação e pendências operacionais.</p></div></header>
<section class="panel"><form method="get" action="/reports" class="form-grid"><label>Condomínio<select name="condo"><option value="">Todos</option><?php foreach($condos as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $condoId===(int)$c['id']?'selected':'' ?>><?= htmlspecialchars($c['name']) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><option value="">Todos</option><?php foreach($statusLabels as $code=>$label): ?><option value="<?= htmlspecialchars($code) ?>" <?= $status===$code?'selected':'' ?>><?= htmlspecialchars($label) ?></option><?php endforeach; ?></select></label><div class="form-actions"><button class="button primary">Filtrar</button><a class="button secondary" href="/reports">Limpar</a></div></form></section>
<div class="stats-grid"><article class="stat-card"><span>Total</span><strong><?= (int)($kpis['total']??0) ?></strong></article><article class="stat-card"><span>Operacionais</span><strong><?= (int)($kpis['operational']??0) ?></strong></article><article class="stat-card"><span>Concluídas</span><strong><?= (int)($kpis['completed']??0) ?></strong></article><article class="stat-card"><span>Com pendências</span><strong><?= (int)($kpis['with_open_nc']??0) ?></strong></article><article class="stat-card"><span>Suspensas</span><strong><?= (int)($kpis['suspended']??0) ?></strong></article><article class="stat-card"><span>Embargadas</span><strong><?= (int)($kpis['embargoed']??0) ?></strong></article></div>
